from flask import Flait, request, jsonify

app = Flait(__name__)

@app.route('/compare', methods=['POST'])
def compare_values():
    """
    Compare two numerical values and return the greater one.

    This API endpoint accepts a POST request with a JSON payload containing two numerical values.
    It returns a JSON response with the greater of the two values.

    The endpoint expects the following JSON format:
    {
        "value1": <first_numerical_value>,
        "value2": <second_numerical_value>
    }

    Example request:
    curl -X POST -H "Content-Type: application/json" -d '{"value1": 5, "value2": 10}' http://localhost:5000/compare

    Example response:
    {
        "greater_value": 10
    }
    """
    data = request.get_json()

    if 'value1' not in data or 'value2' not in data:
        return jsonify({"error": "Both 'value1' and 'value2' are required in the request body"}), 400

    try:
        value1 = float(data['value1'])
        value2 = float(data['value2'])
    except ValueError:
        return jsonify({"error": "Both 'value1' and 'value2' must be numerical values"}), 400

    greater_value = max(value1, value2)

    return jsonify({"greater_value": greater_value})

if __name__ == '__main__':
    app.run(debug=True)
```
