Here's a Python code that uses a backtracking algorithm to solve a Sudoku puzzle. This code assumes that the input is a 2D list where empty cells are represented by 0s.

```python
def is_valid(grid, row, col, num):
    """Check if a number is valid in the given cell."""
    for x in range(9):
        if grid[row][x] == num or grid[x][col] == num:
            return False

    start_row = row - row % 3
    start_col = col - col % 3

    for i in range(3):
        for j in range(3):
            if grid[i + start_row][j + start_col] == num:
                return False

    return True


def solve_sudoku(grid):
    """Solve the Sudoku puzzle using backtracking."""
    for row in range(9):
        for col in range(9):
            if grid[row][col] == 0:
                for num in range(1, 10):
                    if is_valid(grid, row, col, num):
                        grid[row][col] = num
                        if solve_sudoku(grid):
                            return True
                        grid[row][col] = 0  # backtrack
                return False
    return True


def print_grid(grid):
    """Print the Sudoku grid in a user-friendly format."""
    for row in grid:
        for cell in row:
            print(f"{cell} ", end="")
        print()


if __name__ == "__main__":
    grid = [
        [3, 0, 6, 5, 0, 8, 4, 0, 0],
        [5, 2, 0, 0, 0, 0, 0, 0, 0],
        [0, 8, 7, 0, 0, 0, 0, 3, 1],
        [0, 0, 3, 0, 1, 0, 0, 8, 0],
        [9, 0, 0, 8, 6, 3, 0, 0, 5],
        [0, 5, 0, 0, 9, 0, 6, 0, 0],
        [1, 3, 0, 0, 0, 0, 2, 5, 0],
        [0, 0, 0, 0, 0, 0, 0, 7, 4],
        [0, 0, 5, 2, 0, 6, 3, 0, 0]
    ]

    if solve_sudoku(grid):
        print_grid(grid)
    else:
        print("No solution found.")
```

This code defines three functions:

1. `is_valid`: This function checks if a number is valid in a given cell by ensuring that the number doesn't already exist in the same row, column, or 3x3 grid.
2. `solve_sudoku`: This function uses a backtracking algorithm to solve the Sudoku puzzle. It iterates over each cell, and if the cell is empty, it tries to fill it with a number from 1 to 9. If the number is valid, it recursively calls `solve_sudoku` to fill the rest of the grid. If the number is not valid, it backtracks by setting the cell back to 0 and trying the next number.
3. `print_grid`: This function prints the Sudoku grid in a user-friendly format.

The main part of the code initializes a Sudoku grid, solves it using `solve_sudoku`, and prints the result if a solution is found. If no solution is found, it prints "No solution found."

Here's a Python function that uses the `inspect` module to generate a universal JSON serialization from any Python class. This function serializes the class instance to JSON by iterating over the class attributes and their values.

```python
import json
import inspect

def serialize_to_json(obj, skip_private=True):
    """
    Serialize an object to a JSON string.

    Args:
        obj: The object to serialize.
        skip_private (bool, optional): Whether to skip private attributes. Defaults to True.

    Returns:
        str: The serialized object as a JSON string.

    Raises:
        TypeError: If the object is not a class instance or a subclass of `object`.

    Example:
        >>> from datetime import datetime
        >>> class MyClass:
       ...     def __init__(self, name, timestamp):
       ...         self.name = name
       ...         self.timestamp = timestamp
       ...
        >>> my_instance = MyClass("John Doe", datetime.now())
        >>> json_str = serialize_to_json(my_instance)
        >>> print(json_str)
        {"name": "John Doe", "timestamp": "2022-03-15T12:34:56.789123"}
    """

    if not isinstance(obj, object):
        raise TypeError("Object must be an instance of a class or a subclass of object.")

    if skip_private:
        attributes = [
            (name, value)
            for name, value in inspect.getmembers(obj)
            if not name.startswith("__")
        ]
    else:
        attributes = inspect.getmembers(obj)

    return json.dumps({k: _convert_to_serializable(v) for k, v in attributes})


def _convert_to_serializable(value):
    """
    Convert a value to a serializable type.

    Args:
        value: The value to convert.

    Returns:
        A serializable type.

    Example:
        >>> _convert_to_serializable(datetime.now())
        "2022-03-15T12:34:56.789123"
    """

    if isinstance(value, (int, float, str, bool, type(None))):
        return value
    elif isinstance(value, (datetime, date)):
        return value.isoformat()
    elif isinstance(value, set):
        return list(value)
    elif hasattr(value, "__class__"):
        return {
            "class_name": value.__class__.__name__,
            "attributes": serialize_to_json(value, skip_private=False),
        }
    else:
        raise TypeError(f"Object of type {type(value).__name__} is not serializable.")
```

This function serializes the class instance to JSON by iterating over the class attributes and their values. It handles private attributes and serializes the values to a serializable format. The `_convert_to_serializable` function converts the values to a serializable type, such as strings, ISO format dates, lists, or dictionaries. The function raises a `TypeError` if the object is not a class instance or a subclass of `object`.

