class RandomNeuronNetwork:
    def __init__(self, num_inputs, num_neurons, min_bias, max_bias):
        self.num_inputs = num_inputs
        self.num_neurons = num_neurons
        self.min_bias = min_bias
        self.max_bias = max_bias
        self.neurons = self.create_neurons()

    def create_neurons(self):
        return [
            Neuron(
                bias=random.uniform(self.min_bias, self.max_bias),
                input_value=random.uniform(-1, 1)
            )
            for _ in range(self.num_neurons)
        ]

    def calculate_output(self, input_values):
