```python
class Node:
    """A class representing a node in a binary tree."""

    def __init__(self, value):
        """Initialize a node with a given value."""
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    """A class representing a binary tree."""

    def __init__(self, root=None):
        """Initialize a binary tree with a given root node."""
        self.root = Node(root) if root is not None else None

    def insert(self, value):
        """Insert a new node with the given value into the binary tree."""
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, current_node, value):
        """Insert a new node with the given value into the binary tree recursively."""
        if value < current_node.value:
            if current_node.left is None:
                current_node.left = Node(value)
            else:
                self._insert_recursive(current_node.left, value)
        else:
            if current_node.right is None:
                current_node.right = Node(value)
            else:
                self._insert_recursive(current_node.right, value)

    def max_depth(self):
        """Find and return the maximum depth of the binary tree."""
        return self._max_depth_recursive(self.root)

    def _max_depth_recursive(self, node):
        """Find the maximum depth of the binary tree recursively."""
        if node is None:
            return 0
        else:
