        """Describes the current location to the player."""
        locations = {
            "forest": "You are in a dense forest. You can see paths leading in different directions.",
            "treasure": "You have found a hidden treasure! It's a magnificent gold chest.",
            "obstacle": "You encounter a deep river. The current bank is covered in logs and stones."
        }
