    def take_item(self, item):
        """Adds an item to the player's inventory."""
        self.inventory.append(item)
        print(f"You picked up the {item}.")

    def move(self, direction):
        """Moves the player in the specified direction."""
        directions = {
            "north": "forest2",
            "east": "forest3",
            "south": "forest4",
            "west": "forest1"
        }
        next_location = directions.get(direction)
        if next_location:
            self.current_location = next_location
            self.describe_location()
        else:
            print("You can't go that way.")

    def find_treasure(self):
        """Locates and collects the treasure."""
        self.current_location = "treasure"
        self.describe_location()
        self.take_item("gold chest")

    def overcome_obstacle(self):
        """Overcomes the obstacle and continues the game."""
        self.current_location = "forest"
        self.describe_location()
        self.move("east")

    def game_over_handler(self):
        """Handles the game over condition."""
        self.game_over = True
        print("Game over! You found the treasure and escaped the forest.")

    def play(self):
        """Starts the game and guides the player through it."""
        self.describe_location()
        while not self.game_over:
            action = input("What do you want to do? ").lower().split()
            if len(action) == 0:
