def transform_text(input_text: str, transformation_type: str) -> str:
    """
    This function takes an input text and a transformation type as arguments and returns the transformed text.

    Args:
        input_text (str): The input text to be transformed.
        transformation_type (str): The type of transformation to be applied. Options include 'uppercase', 'lowercase', 'capitalize', 'title','replace', 'insert', 'delete'.

    Returns:
        str: The transformed text.

    Raises:
        ValueError: If the transformation type is not recognized.

    Examples:
        >>> transform_text("Hello World", "uppercase")
        "HELLO WORLD"
        >>> transform_text("hello world", "lowercase")
        "hello world"
        >>> transform_text("HeLLo WoRLd", "capitalize")
        "Hello World"
        >>> transform_text("HeLLo WoRLd", "title")
        "Hello World"
        >>> transform_text("HeLLo WoRLd", "replace", "world", "earth")
        "HeLLo Earth"
        >>> transform_text("HeLLo WoRLd", "insert", "planet", "after")
        "HeLLo Planet WoRLd"
        >>> transform_text("HeLLo WoRLd", "delete", "WoRLd")
        "HeLLo"
    """

    if transformation_type == "uppercase":
        return input_text.upper()
    elif transformation_type == "lowercase":
        return input_text.lower()
    elif transformation_type == "capitalize":
        return input_text.capitalize()
    elif transformation_type == "title":
        return input_text.title()
    elif transformation_type == "replace":
        return input_text.replace(*input_text.replace.args[1:])
    elif transformation_type == "insert":
        index = input_text.index(input_text.replace.args[2])
        return input_text[:index] + input_text.replace.args[1] + input_text[index:]
    elif transformation_type == "delete":
