    This function takes a string representing a mathematical expression and returns a tree of Nodes, where each Node contains a value and two children (left and right).

    :param expression: str, a string representing a mathematical expression
    :return: Node, the root of the tree
    """
    def build_tree(tokens):
        if not tokens:
            return None
        token = tokens.pop(0)
        if token.isalnum():
            return Node(token)
        else:
            node = Node(token)
            node.left = build_tree(tokens)
            node.right = build_tree(tokens)
            return node

    tokens = expression.strip().split()
    return build_tree(tokens)
