class BinaryTree:
    """A binary tree."""

    def __init__(self, root=None):
        """Initializes a new binary tree with the given root node."""
        self.root = root

    def __str__(self):
        """Returns a string representation of this binary tree."""
        if self.root is None:
            return ""
        return str(self.root) + "\n" + self._recurse_subtree(self.root.left) + self._recurse_subtree(self.root.right)

    def _recurse_subtree(self, node):
        """Recursively generates a string representation of the subtree rooted at the given node."""
        if node is None:
            return ""
        return str(node) + "\n" + self._recurse_subtree(node.left) + self._recurse_subtree(node.right)

