```python
class Node:
    def __init__(self, char):
        self.char = char
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, char):
        """Insert a new character into the binary tree.

        Args:
            char (str): The character to be inserted.

        Returns:
            None
        """
        if not self.root:
            self.root = Node(char)
        else:
            self._insert_recursive(self.root, char)

    def _insert_recursive(self, node, char):
        """Recursive helper function for inserting a character.

        Args:
            node (Node): The current node.
            char (str): The character to be inserted.

        Returns:
            None
        """
        if char < node.char:
            if node.left is None:
                node.left = Node(char)
            else:
                self._insert_recursive(node.left, char)
        elif char > node.char:
            if node.right is None:
                node.right = Node(char)
            else:
                self._insert_recursive(node.right, char)

    def search(self, char):
        """Search for a given character in the binary tree.

        Args:
            char (str): The character to be searched.

        Returns:
            bool: True if the character is found, False otherwise.
        """
        return self._search_recursive(self.root, char)

    def _search_recursive(self, node, char):
        """Recursive helper function for searching a character.

        Args:
            node (Node): The current node.
            char (str): The character to be searched.

        Returns:
            bool: True if the character is found, False otherwise.
        """
        if node is None:
            return False
        if char == node.char:
            return True
        if char < node.char:
            return self._search_recursive(node.left, char)
        else:
            return self._search_recursive(node.right, char)
```

