def is_valid_number(board, row, col, num):
    # Check if the number is already present in the current row
    if num in board[row]:
        return False

    # Check if the number is already present in the current column
    if num in [board[i][col] for i in range(9)]:
        return False

    # Check if the number is already present in the current 3x3 sub-grid
    sub_grid_row = (row // 3) * 3
    sub_grid_col = (col // 3) * 3
    for i in range(sub_grid_row, sub_grid_row + 3):
        for j in range(sub_grid_col, sub_grid_col + 3):
            if board[i][j] == num:
                return False

    return True


