        self.left = None
        self.right = None


class BinarySearchTree:
    """A Binary Search Tree (BST).

    The BST is a binary tree where each node has at most two children,
    and the value of each node is greater than or equal to the values
    in its left subtree and less than or equal to the values in its
    right subtree.
    """

    def __init__(self):
        self.root = None

    def insert(self, value):
        """Inserts a value into the BST.

        Args:
            value: The value to be inserted.

        Returns:
            The root node of the updated BST.
        """
        if not self.root:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)
        return self.root

    def _insert_recursive(self, current_node, value):
        """A recursive helper function for inserting a value into the BST.

        Args:
            current_node: The current node being processed.
            value: The value to be inserted.
        """
        if value < current_node.value:
            if not current_node.left:
                current_node.left = Node(value)
            else:
                self._insert_recursive(current_node.left, value)
        else:
            if not current_node.right:
                current_node.right = Node(value)
            else:
                self._insert_recursive(current_node.right, value)

    def search(self, value):
        """Searches for a value in the BST.

        Args:
            value: The value to be searched.

        Returns:
            True if the value is found, False otherwise.
        """
        return self._search_recursive(self.root, value)

    def _search_recursive(self, current_node, value):
        """A recursive helper function for searching a value in the BST.

        Args:
            current_node: The current node being processed.
            value: The value to be searched.

        Returns:
            True if the value is found, False otherwise.
        """
        if not current_node:
            return False
        elif current_node.value == value:
            return True
        elif value < current_node.value:
            return self._search_recursive(current_node.left, value)
        else:
            return self._search_recursive(current_node.right, value)
