class Node:
    """
    A node in a binary search tree.

    Attributes:
        key: The key value of the node.
        left: The left child of the node.
        right: The right child of the node.
    """
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

    def insert(self, key):
        """
        Insert a new key into the binary search tree.

        Args:
            key: The key to be inserted.

        Returns:
            The root node of the modified binary search tree.
        """
        if not self.key:
            self.key = key
            return self
        elif key < self.key:
            if self.left:
                self.left.insert(key)
            else:
                self.left = Node(key)
        else:
            if self.right:
                self.right.insert(key)
            else:
                self.right = Node(key)
        return self

    def search(self, key):
        """
        Search for a key in the binary search tree.

        Args:
            key: The key to be searched.

        Returns:
            True if the key is found, False otherwise.
        """
        if self.key == key:
            return True
        elif key < self.key and self.left:
            return self.left.search(key)
        elif key > self.key and self.right:
            return self.right.search(key)
        return False

    def delete(self, key):
        """
        Delete a key from the binary search tree.

        Args:
            key: The key to be deleted.

        Returns:
            The root node of the modified binary search tree.
        """
        if not self.key:
            return None
        elif key < self.key and self.left:
            self.left = self.left.delete(key)
        elif key > self.key and self.right:
            self.right = self.right.delete(key)
        else:
            if not self.left and not self.right:
                return None
            elif self.left and not self.right:
                return self.left
            elif not self.left and self.right:
                return self.right
            else:
                temp_node = self.right
                while temp_node.left:
                    temp_node = temp_node.left
                self.key = temp_node.key
                self.right = self.right.delete(self.key)
        return self
