```python
import json

def flatten_json(y):
    """
    Flattens a nested JSON object into a single level dictionary.

    Args:
        y (dict or list): The JSON object to be flattened.

    Returns:
        dict: A flattened dictionary.

    Examples:
        >>> flatten_json({"a": {"b": {"c": 1, "d": 2}, "e": 3}})
        {'a.b.c': 1, 'a.b.d': 2, 'a.e': 3}
    """

    out = {}

    def flatten(x, name=''):
        if type(x) is dict:
            for a in x:
                flatten(x[a], name + a + '.')
        elif type(x) is list:
            i = 0
            for a in x:
                flatten(a, name + str(i) + '.')
                i += 1
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

# Example usage
json_obj = {
    "a": {
        "b": {
            "c": 1,
            "d": 2
        },
        "e": 3
    }
}

flat_json = flatten_json(json_obj)
print(flat_json)
```

