class Node:
    """A class to represent an individual node in a linked list."""

    def __init__(self, data=None):
        """Initialize the node with the given data."""
        self.data = data
        self.next = None


class LinkedList:
    """A class to implement a linked list with add, delete, and print functionalities."""

    def __init__(self):
        """Initialize the linked list with a head node."""
        self.head = Node()

    def add(self, data):
        """Add a new node with the given data to the end of the linked list."""
        new_node = Node(data)
        if not self.head.next:
            self.head.next = new_node
        else:
            current = self.head.next
            while current.next:
                current = current.next
            current.next = new_node

    def delete(self, data):
        """Delete the first node with the given data from the linked list."""
        if not self.head.next:
            return
        if self.head.next.data == data:
            self.head.next = self.head.next.next
        else:
            current = self.head.next
            while current.next:
                if current.next.data == data:
                    current.next = current.next.next
                    return
                current = current.next

    def print_list(self):
        """Print the data in all nodes of the linked list."""
        current = self.head.next
        while current:
            print(current.data, end=" ")
            current = current.next
        print()
