```python
import math
from collections import defaultdict

class NaiveBayesClassifier:
    def __init__(self):
        self.word_freq = defaultdict(lambda: defaultdict(int))
        self.class_count = defaultdict(int)
        self.total_count = 0

    def train(self, labeled_emails):
        for email, label in labeled_emails:
            self.class_count[label] += 1
            self.total_count += 1
            for word, freq in email.items():
                self.word_freq[label][word] += freq
                self.word_freq[label]["total"] += freq

    def classify(self, email):
        probabilities = {}
        for label, freq in self.class_count.items():
            probabilities[label] = (freq + 1) / (self.total_count + len(self.word_freq))
            for word, word_freq in email.items():
                probabilities[label] *= self.word_freq[label].get(word, 1) / self.word_freq[label]["total"]
        return max(probabilities, key=probabilities.get)

def is_spam(email):
    """
    Classify an email as spam or not spam using a Naive Bayes classifier.

    Args:
        email (dict): A dictionary where keys are feature names and values are feature values.

    Returns:
        str:'spam' or 'not spam'
    """
    classifier = NaiveBayesClassifier()
    classifier.train(labeled_emails)  # Replace labeled_emails with your labeled dataset
    return classifier.classify(email)
```

