class Stack:
    def __init__(self):
        self.items = []

    def is_empty(self):
        return not bool(self.items)

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()

    def peek(self):
        if not self.is_empty():
            return self.items[-1]

    def size(self):
        return len(self.items)


def precedence(op):
    if op == '+' or op == '-':
        return 1
    if op == '*' or op == '/':
        return 2
    return 0


def infix_to_postfix(infix_expr):
    postfix_expr = ''
    operators_stack = Stack()

    for token in infix_expr:
        if token.isalnum():
            postfix_expr += token +''
        elif token in ['+', '-', '*', '/', '(', ')']:
            while (not operators_stack.is_empty() and
                   precedence(operators_stack.peek()) >= precedence(token)):
                postfix_expr += operators_stack.pop() +''
            operators_stack.push(token)
        elif token == '(':
            operators_stack.push(token)
        elif token == ')':
            top_token = operators_stack.pop()
            while top_token!= '(':
                postfix_expr += top_token +''
                top_token = operators_stack.pop()
            operators_stack.pop()

    while not operators_stack.is_empty():
        postfix_expr += operators_stack.pop() +''

    return postfix_expr


if __name__ == "__main__":
    infix_expr = "A + B * ( C + D ) - ( E * F + G )"
    print(f"Infix expression: {infix_expr}")
    print(f"Postfix expression: {infix_to_postfix(infix_expr)}")
```

