Here's a simple implementation of a binary tree structure and associated functions in Python:

```python
class Node:
    """A node in a binary tree."""

    def __init__(self, key):
        """Initialize a new node with the given key."""
        self.left = None
        self.right = None
        self.val = key

    def __repr__(self):
        """Return a string representation of this node."""
        return f'Node({self.val})'


class BinaryTree:
    """A binary tree."""

    def __init__(self):
        """Initialize an empty binary tree."""
        self.root = None

    def insert(self, key):
        """Insert the given key into the tree."""
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert_recursive(self.root, key)

    def _insert_recursive(self, node, key):
        """Insert the given key into the tree, recursively."""
        if key < node.val:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert_recursive(node.left, key)
        else:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert_recursive(node.right, key)

    def search(self, key):
        """Search for the given key in the tree."""
        return self._search_recursive(self.root, key)

    def _search_recursive(self, node, key):
        """Search for the given key in the tree, recursively."""
        if node is None or node.val == key:
            return node is not None

        if key < node.val:
            return self._search_recursive(node.left, key)

        return self._search_recursive(node.right, key)


if __name__ == '__main__':
    """Example usage."""
    tree = BinaryTree()
    tree.insert(50)
    tree.insert(30)
    tree.insert(20)
    tree.insert(40)
    tree.insert(70)
    tree.insert(60)
    tree.insert(80)

    print(tree.search(20))  # True
    print(tree.search(90))  # False
```

This code defines a `Node` class to represent a node in a binary tree, and a `BinaryTree` class to manage the tree as a whole. The `BinaryTree` class has methods to insert and search for elements in the tree.

The `insert` method adds a new node with the given key to the tree. If the tree is empty, the new node becomes the root. Otherwise, the method recursively traverses the tree, starting from the root, and inserts the new node in the appropriate position based on the key value.

The `search` method checks if the given key exists in the tree. It uses the `_search_recursive` method to traverse the tree, starting from the root, and returns `True` if the key is found and `False` otherwise.

